const resp = $json;
const leadId = $('Render Prompt').item.json.leadId;

if (resp.error) {
  return [{ json: { valid: false, reason: `HTTP error: ${JSON.stringify(resp.error)}`, leadId } }];
}

const block = (resp.content || [])[0];
if (!block || typeof block.text !== 'string') {
  return [{ json: { valid: false, reason: 'no text content block in response', leadId } }];
}

let text = block.text.trim();
text = text.replace(/^```(json)?\n?/, '').replace(/\n?```$/, '');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { valid: false, reason: `JSON parse failed: ${e.message}`, leadId } }];
}

const errors = [];
const dimKeys = ['company_fit', 'pain_signals', 'buying_intent', 'tech_maturity', 'market_timing'];

if (typeof parsed.company_summary !== 'string') errors.push('company_summary must be string');
if (!Array.isArray(parsed.buying_signals)) errors.push('buying_signals must be array');
if (!Array.isArray(parsed.objection_risks)) errors.push('objection_risks must be array');

if (!parsed.dimensions || typeof parsed.dimensions !== 'object') {
  errors.push('dimensions missing');
} else {
  for (const key of dimKeys) {
    const d = parsed.dimensions[key];
    if (!d) { errors.push(`dimensions.${key} missing`); continue; }
    if (typeof d.score !== 'number' || d.score < 0 || d.score > 100) errors.push(`dimensions.${key}.score must be 0-100`);
    if (typeof d.reasoning !== 'string') errors.push(`dimensions.${key}.reasoning must be string`);
    if (!Array.isArray(d.evidence)) errors.push(`dimensions.${key}.evidence must be array`);
  }
}

if (!parsed.observed_headcount || typeof parsed.observed_headcount !== 'object') {
  errors.push('observed_headcount missing');
} else {
  if (typeof parsed.observed_headcount.value !== 'number') errors.push('observed_headcount.value must be number');
  if (parsed.observed_headcount.source_quote !== null && typeof parsed.observed_headcount.source_quote !== 'string') {
    errors.push('observed_headcount.source_quote must be string or null');
  }
}

if (!parsed.disqualification || typeof parsed.disqualification !== 'object') {
  errors.push('disqualification missing');
} else {
  if (typeof parsed.disqualification.hits_disqualifier !== 'boolean') errors.push('disqualification.hits_disqualifier must be boolean');
  if (parsed.disqualification.disqualifier_id !== null && typeof parsed.disqualification.disqualifier_id !== 'string') {
    errors.push('disqualification.disqualifier_id must be string or null');
  }
  if (typeof parsed.disqualification.reasoning !== 'string') errors.push('disqualification.reasoning must be string');
  if (!Array.isArray(parsed.disqualification.evidence)) errors.push('disqualification.evidence must be array');
}

if (!Array.isArray(parsed.fields_used)) errors.push('fields_used must be array');
if (typeof parsed.draft_email !== 'string') errors.push('draft_email must be string');

// --- post-model semantic validation (issue #38 spec section 4) ---
// Runs only once the response is structurally well-formed. Failures here are added to
// the same `errors` array as schema failures, so they reuse the existing
// retry-once -> dead-letter -> alert path with no new failure mode.
if (errors.length === 0) {
  const config = $('Render Prompt').item.json.config;
  const lead = $('Supabase - Get Lead').item.json;
  const configuredIds = new Set(config.hard_disqualifiers.map(d => d.id));
  const dq = parsed.disqualification;

  // Check 1: disqualifier_id must be a configured id when hits_disqualifier is true,
  // and null when false. Exact string match.
  if (dq.hits_disqualifier === true) {
    if (!dq.disqualifier_id || !configuredIds.has(dq.disqualifier_id)) {
      errors.push(`disqualification.disqualifier_id "${dq.disqualifier_id}" is not a configured id`);
    }
  } else if (dq.disqualifier_id !== null) {
    errors.push('disqualification.disqualifier_id must be null when hits_disqualifier is false');
  }

  // Check 2: company_too_large requires an observed_headcount the model actually
  // extracted from <lead> - value > 1000, a non-null source_quote, and that quote
  // present as an EXACT substring of the rendered <lead> block. Exact substring, not
  // token overlap: a headcount is a short factual string, so if it isn't verbatim in
  // the source, the model invented it.
  if (dq.hits_disqualifier === true && dq.disqualifier_id === 'company_too_large') {
    const headcount = parsed.observed_headcount || {};
    const leadEnrichmentJson = JSON.stringify(lead.enrichment || {}, null, 2);
    const leadMessage = lead.message || '(no message provided)';
    const leadBlock = leadEnrichmentJson + '\n' + leadMessage;

    if (typeof headcount.value !== 'number' || headcount.value <= 1000) {
      errors.push('company_too_large requires observed_headcount.value > 1000');
    } else if (!headcount.source_quote || typeof headcount.source_quote !== 'string') {
      errors.push('company_too_large requires a non-null observed_headcount.source_quote');
    } else if (!leadBlock.includes(headcount.source_quote)) {
      errors.push('company_too_large observed_headcount.source_quote is not an exact substring of the supplied lead data');
    }
  }

  // Check 3: draft_email must be non-empty regardless of disqualification status.
  if (!parsed.draft_email || parsed.draft_email.trim() === '') {
    errors.push('draft_email must be a non-empty string regardless of disqualification status');
  }
}

if (errors.length > 0) {
  return [{ json: { valid: false, reason: errors.join('; '), leadId } }];
}

// --- evidence-provenance check (log-only, issue #38 spec section 4 check 4) ---
// Fuzzy token-overlap matching, distinct from check 2's exact-substring matcher above.
// Provenance is fuzzy and will false-positive on legitimate paraphrase, so this warns
// rather than fails - promotion to enforcing is tracked in a follow-up issue.
const config = $('Render Prompt').item.json.config;
const lead = $('Supabase - Get Lead').item.json;
const leadEnrichmentJson = JSON.stringify(lead.enrichment || {}, null, 2);
const leadMessage = lead.message || '(no message provided)';
const normalize = (s) => (s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ');
const haystackNorm = normalize(leadEnrichmentJson + ' ' + leadMessage);
const warnings = [];

function checkEvidence(list, label) {
  for (const item of (list || [])) {
    const tokens = normalize(item).split(/\s+/).filter(t => t.length >= 4);
    if (tokens.length === 0) continue;
    const matched = tokens.filter(t => haystackNorm.includes(t)).length;
    const ratio = matched / tokens.length;
    if (ratio < 0.6) {
      warnings.push(`${label}: "${item}" (token overlap ${(ratio * 100).toFixed(0)}%)`);
    }
  }
}

for (const key of dimKeys) {
  checkEvidence(parsed.dimensions[key].evidence, `dimensions.${key}.evidence`);
}
checkEvidence(parsed.disqualification.evidence, 'disqualification.evidence');

// --- disqualifier reasoning-vs-definition consistency (log-only, competitor-axis finding) ---
// disqualifier_id being a member of the configured set (checked above, enforcing) doesn't
// mean the model's stated reasoning/evidence actually supports THAT id's definition - the
// Sanity fixture (#35's named case) reproducibly disqualified as obvious_competitor on
// generic "automation/platform" overlap that never engages the definition's actual category
// terms (lead enrichment/scoring/routing/RevOps automation/CRM delivery). Log-only: this is
// a coarse token-overlap heuristic, not a semantic check, and will have false positives -
// promotion to enforcing is tracked in a follow-up issue, same pattern as evidence provenance.
if (parsed.disqualification.hits_disqualifier === true) {
  const matchedDisqualifier = config.hard_disqualifiers.find(hd => hd.id === parsed.disqualification.disqualifier_id);
  if (matchedDisqualifier) {
    // Compare against the definition's first sentence only - the positive category
    // statement - not the full definition, which also carries negative exclusion lists
    // ("Productivity tools... are NOT competitors") that would otherwise dilute overlap
    // for genuinely correct matches too.
    const positiveClause = matchedDisqualifier.definition.split('.')[0];
    const defTokens = normalize(positiveClause).split(/\s+/).filter(t => t.length >= 4);
    const justificationNorm = normalize(
      (parsed.disqualification.evidence || []).join(' ') + ' ' + (parsed.disqualification.reasoning || '')
    );
    const defMatched = defTokens.filter(t => justificationNorm.includes(t)).length;
    const defRatio = defTokens.length > 0 ? defMatched / defTokens.length : 0;
    if (defRatio < 0.15) {
      warnings.push(`disqualification: disqualifier_id "${parsed.disqualification.disqualifier_id}" evidence/reasoning has low overlap (${(defRatio * 100).toFixed(0)}%) with its configured definition - possible off-definition disqualification labeled with a valid id`);
    }
  }
}

if (warnings.length > 0) {
  console.log(`Evidence provenance warnings for lead ${leadId}: ${warnings.join(' | ')}`);
}

const usage = resp.usage || {};
return [{
  json: {
    valid: true,
    parsed,
    leadId,
    input_tokens: usage.input_tokens || 0,
    output_tokens: usage.output_tokens || 0,
    validation_warnings: warnings
  }
}];

