    company_fit:   { evidence: [], reasoning: skippedReasoning, score: 0 },
    pain_signals:  { evidence: [], reasoning: skippedReasoning, score: 0 },
    buying_intent: { evidence: [], reasoning: skippedReasoning, score: 0 },
    tech_maturity: { evidence: [], reasoning: skippedReasoning, score: 0 },
    market_timing: { evidence: [], reasoning: skippedReasoning, score: 0 }
  },
  observed_headcount: { value: 0, source_quote: null },
