    hits_disqualifier: true,
    disqualifier_id: 'obvious_competitor',
    reasoning: `Company name "${lead.company}" matched an entry in config.competitor_list.`,
    evidence: [lead.company || '']
  },
  disqualifier_source: 'code_list',
  fields_used: ['company'],
  draft_email: null
};

